import java.util.*;class Solution{List<List<Integer>>o=new ArrayList<>();void f(int[]a,int st,int r,List<Integer>v){if(r==0){o.add(new ArrayList<>(v));return;}for(int i=st;i<a.length&&a[i]<=r;i++){if(i>st&&a[i]==a[i-1])continue;v.add(a[i]);f(a,i+1,r-a[i],v);v.remove(v.size()-1);}}public List<List<Integer>> combinationSum2(int[]a,int t){Arrays.sort(a);f(a,0,t,new ArrayList<>());return o;}}
